namespace Libra2Model {

/**
 * @brief Converts CW volume (L) to mass (kg).
 *
 * @param volume CW volume, V (L)
 *
 * @note From Eq. 28 (`G_Estimating-State.jpg`):
 *         m_cw = ρ_water·V
 */
double CwMass(const double& volume) {
    return kWaterDensity * volume;  // Eq. 28
}

/**
 * @brief CW gravity torque (Nm) about pitch joint O.
 *
 * @param cw_moment CW gravity moment along arm, m_cw·r_P (kg·m)
 * @param cw_hang_moment CW gravity moment normal to arm, m_cw·q_P (kg·m)
 * @param grav Gravitational acceleration, g (m/s²)
 * @param theta Pitch angle, θ (rad)
 *
 * @note Code-specific extension of Eq. 29b (`G_Estimating-State.jpg`): the
 *       hang points are q_P from O, normal to arm (Eq. 2 with q = q_P):
 *         τ_g2(θ) = m_cw·g·(r_P·cos θ + q_P·sin θ)
 */
double CwGravTorque(const double& cw_moment, const double& cw_hang_moment,
                    const double& grav, const double& theta) {
    // Eq. 29b (extended)
    return grav
           * (cw_moment * std::cos(theta) + cw_hang_moment * std::sin(theta));
}

/**
 * @brief Arm's own gravity torque (Nm): measured torque minus CW's share.
 *
 * @param torque_meas Measured torque about pitch joint, τ_meas(θ) (Nm)
 * @param cw_grav_torque CW gravity torque, τ_g2(θ) (Nm), from `CwGravTorque()`
 *
 * @note From Eq. 29a (`G_Estimating-State.jpg`):
 *         τ_g1(θ) = τ_meas(θ) − τ_g2(θ)
 */
double ArmGravTorque(const double& torque_meas, const double& cw_grav_torque) {
    return torque_meas - cw_grav_torque;  // Eq. 29a
}

/**
 * @brief Arm's gravity torque (Nm) at level, from one measurement at any angle.
 *
 * @param arm_torque Arm's own gravity torque at `theta`, τ_g1(θ) (Nm)
 * @param theta Pitch angle, θ (rad)
 * @param arm_hang_torque Arm hang torque, m_arm·h_1·g (Nm)
 *
 * @note Returns none if cos θ is too small.
 *
 * @note From Eq. 34 (`H_Holding-Torque-at-any-Angle.jpg`):
 *         τ_g1,0 = (τ_g1(θ) − g·m_arm·h_1·sin θ) / cos θ
 */
std::optional<double> ArmLevelTorque(const double& arm_torque,
                                     const double& theta,
                                     const double& arm_hang_torque) {
    // Eq. 34 (Eq. 31 when theta = 0)
    const double c = std::cos(theta);
    if (std::abs(c) < kMinCosForBalance) {
        return std::nullopt;
    }
    return (arm_torque - arm_hang_torque * std::sin(theta)) / c;
}

/**
 * @brief Solves arm's level and hang torques from two-angle measurements.
 *
 * @param arm_torque_a Arm's own gravity torque at angle a, τ_g1(θ_a) (Nm)
 * @param theta_a Angle a, θ_a (rad)
 * @param arm_torque_b Arm's own gravity torque at angle b, τ_g1(θ_b) (Nm)
 * @param theta_b Angle b, θ_b (rad)
 * @param[out] arm_level_torque Arm gravity torque at level, τ_g1,0 (Nm)
 * @param[out] arm_hang_torque Arm hang torque, m_arm·h_1·g (Nm)
 *
 * @note Fails if the angles are too close together.
 *
 * @note From Eq. 35c (`H_Holding-Torque-at-any-Angle.jpg`):
 *         τ_g1,0 = (τ_g1(θ_a)·sin θ_b − τ_g1(θ_b)·sin θ_a) / sin(θ_b − θ_a)
 *         m_arm·h_1·g = (τ_g1(θ_b)·cos θ_a − τ_g1(θ_a)·cos θ_b)
 *                       / sin(θ_b − θ_a)
 */
bool SolveTwoAngle(const double& arm_torque_a, const double& theta_a,
                   const double& arm_torque_b, const double& theta_b,
                   double& arm_level_torque, double& arm_hang_torque) {
    // Eq. 35
    const double s = std::sin(theta_b - theta_a);
    if (std::abs(s) < std::sin(0.5 * Motion::kMinAngleSeparation)) {
        return false;
    }
    arm_level_torque = (arm_torque_a * std::sin(theta_b)
                        - arm_torque_b * std::sin(theta_a))
                       / s;
    arm_hang_torque = (arm_torque_b * std::cos(theta_a)
                       - arm_torque_a * std::cos(theta_b))
                      / s;
    return true;
}

/**
 * @brief Net gravity torque (Nm) about pitch joint from arm and CW.
 *
 * @param arm_level_torque Arm gravity torque at level, τ_g1,0 (Nm)
 * @param arm_hang_torque Arm hang torque, m_arm·h_1·g (Nm)
 * @param cw_moment CW gravity moment along arm, m_cw·r_P (kg·m)
 * @param cw_hang_moment CW gravity moment normal to arm, m_cw·q_P (kg·m)
 * @param grav Gravitational acceleration, g (m/s²)
 * @param theta Pitch angle, θ (rad)
 *
 * @note Code-specific extension of Eq. 36
 *       (`H_Holding-Torque-at-any-Angle.jpg`), with the CW torque from
 *       `CwGravTorque()`:
 *         τ_ext,g(θ) = (τ_g1,0 + m_cw·g·r_P)·cos θ
 *                      + (m_arm·h_1·g + m_cw·g·q_P)·sin θ
 */
double NetGravTorque(const double& arm_level_torque,
                     const double& arm_hang_torque, const double& cw_moment,
                     const double& cw_hang_moment, const double& grav,
                     const double& theta) {
    // Eq. 36 (extended)
    return (arm_level_torque + grav * cw_moment) * std::cos(theta)
           + (arm_hang_torque + grav * cw_hang_moment) * std::sin(theta);
}

/**
 * @brief Total sine coefficient of the net gravity torque (Nm); the arm is
 *        stable at an equilibrium only while it is negative.
 *
 * @param arm_hang_torque Arm hang torque, m_arm·h_1·g (Nm)
 * @param cw_hang_moment CW gravity moment normal to arm, m_cw·q_P (kg·m)
 * @param grav Gravitational acceleration, g (m/s²)
 *
 * @note Code-specific extension of Eq. 26c (`F_Stability.jpg`), with S taken
 *       from `NetGravTorque()`:
 *         τ' = (m_arm·h_1·g + m_cw·g·q_P) / cos θ*
 */
double StabilityTorque(const double& arm_hang_torque,
                       const double& cw_hang_moment, const double& grav) {
    return arm_hang_torque + grav * cw_hang_moment;
}

/**
 * @brief Actuator torque (Nm) to follow reference motion while canceling
 *        gravity.
 *
 * @param inertia Moment of inertia (kg·m²)
 * @param inertia_rate Rate of change of inertia (kg·m²/s)
 * @param friction_viscous Viscous friction coefficient, b (Nm·s/rad)
 * @param friction_coulomb Coulomb friction torque, τ_c (Nm)
 * @param ref_acc Reference acceleration, θ̈_ref (rad/s²)
 * @param ref_vel Reference velocity, θ̇_ref (rad/s)
 * @param net_grav_torque Net gravity torque at MEASURED angle, τ_ext,g(θ) (Nm)
 *
 * @note Result is not clamped.
 *
 * @note From Eq. 37 (`I_Controller.jpg`):
 *         τ_actuator = I·θ̈_ref + (b + İ)·θ̇_ref + τ_c·sign(θ̇_ref)
 *                      − τ_ext,g(θ)
 */
double TorqueCommand(const double& inertia, const double& inertia_rate,
                     const double& friction_viscous,
                     const double& friction_coulomb, const double& ref_acc,
                     const double& ref_vel, const double& net_grav_torque) {
    // Eq. 37
    return inertia * ref_acc + (friction_viscous + inertia_rate) * ref_vel
           + friction_coulomb * Sign(ref_vel) - net_grav_torque;
}

/**
 * @brief Effective CW moment (kg·m) that balances the arm at a given angle.
 *
 * @param arm_level_torque Arm gravity torque at level, τ_g1,0 (Nm)
 * @param arm_hang_torque Arm hang torque, m_arm·h_1·g (Nm)
 * @param grav Gravitational acceleration, g (m/s²)
 * @param theta Angle to balance at, θ (rad)
 *
 * @note Returns none if cos θ is too small.
 *
 * @note Code-specific extension of Eq. 38 (`I_Controller.jpg`). Since r_P
 *       varies with CW volume and the hang points sit q_P from O,
 *       `CwModel::MassForMoment()` inverts the effective moment instead of
 *       dividing by a fixed r_P:
 *         m_cw,bal·(r_P + q_P·tan θ) = −(τ_g1,0 + m_arm·h_1·g·tan θ) / g
 */
std::optional<double> BalanceCwMoment(const double& arm_level_torque,
                                      const double& arm_hang_torque,
                                      const double& grav, const double& theta) {
    // Eq. 38 (extended)
    if (std::abs(std::cos(theta)) < kMinCosForBalance) {
        return std::nullopt;
    }
    return -(arm_level_torque + arm_hang_torque * std::tan(theta)) / grav;
}

/**
 * @brief Net gravity torque (Nm) the arm will see at target angle with the
 *        current CW.
 *
 * @param grav Gravitational acceleration, g (m/s²)
 * @param theta_tgt Target angle, θ_tgt (rad)
 * @param cw_moment_eff Current effective CW moment at target (kg·m), from
 *                      `CwModel::EffectiveMoment()`
 * @param cw_moment_bal Effective CW moment balancing arm at target (kg·m),
 *                      from `BalanceCwMoment()`
 *
 * @note Code-specific extension of Eq. 39 (`I_Controller.jpg`), with the
 *       effective moments of `BalanceCwMoment()`:
 *         τ_ext,g(θ_tgt) = g·cos θ_tgt·(M_eff(m_cw) − M_eff(m_cw,bal))
 */
double TargetNetGravTorque(const double& grav, const double& theta_tgt,
                           const double& cw_moment_eff,
                           const double& cw_moment_bal) {
    // Eq. 39 (extended)
    return grav * std::cos(theta_tgt) * (cw_moment_eff - cw_moment_bal);
}

/**
 * @brief Least-squares line through friction sweep results: drag vs. speed.
 *
 * @param speeds Sweep speeds, v (rad/s)
 * @param drags Drag at each speed, (τ_up − τ_down) / 2 (Nm)
 * @param[out] coulomb Intercept, τ_c (Nm)
 * @param[out] viscous Slope, b (Nm·s/rad)
 * @param[out] residual_rms RMS of fit residuals (Nm)
 *
 * @note Fails with fewer than two distinct speeds.
 *
 * @note From E8 (`FINDING_ACTUATOR_FRICTION.md`):
 *         (τ_up − τ_down) / 2 = b·v + τ_c
 */
bool FitFrictionLine(const std::vector<double>& speeds,
                     const std::vector<double>& drags, double& coulomb,
                     double& viscous, double& residual_rms) {
    const std::size_t n = speeds.size();
    if (n < 2 || drags.size() != n) {
        return false;
    }

    double mean_v = 0.0;
    double mean_f = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        mean_v += speeds[i];
        mean_f += drags[i];
    }
    mean_v /= static_cast<double>(n);
    mean_f /= static_cast<double>(n);

    double s_vv = 0.0;
    double s_vf = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        s_vv += (speeds[i] - mean_v) * (speeds[i] - mean_v);
        s_vf += (speeds[i] - mean_v) * (drags[i] - mean_f);
    }
    if (!(s_vv > 0.0)) {
        return false;
    }

    viscous = s_vf / s_vv;
    coulomb = mean_f - viscous * mean_v;

    double sum_sq = 0.0;
    for (std::size_t i = 0; i < n; ++i) {
        const double r = drags[i] - (coulomb + viscous * speeds[i]);
        sum_sq += r * r;
    }
    residual_rms = std::sqrt(sum_sq / static_cast<double>(n));
    return true;
}

}  // namespace Libra2Model

//------------------------------------------------------------------------------
// !Rest Sampler
//------------------------------------------------------------------------------

/**
 * @brief Discards the running window.
 */
void RestSampler::Reset() {
    count_ = 0;
    t_elapsed_s_ = 0.0;
    sum_theta_ = 0.0;
    sum_torque_ = 0.0;
    sum_volume_ = 0.0;
}

/**
 * @brief Adds one cycle of measurements; gives the averages once the window is
 *        complete (none until then).
 *
 * @param dt Time since last cycle (s)
 * @param pos Measured angle, θ (rad)
 * @param vel Measured velocity, θ̇ (rad/s)
 * @param torque_actuator Measured actuator torque (Nm)
 * @param trajectory_active Whether a trajectory is running
 * @param volume Latest CW volume (L), if known
 */
std::optional<Motion::RestSample> RestSampler::Add(
    const double& dt, const double& pos, const double& vel,
    const double& torque_actuator, const bool& trajectory_active,
    const std::optional<double>& volume) {
    const bool still = !trajectory_active && std::abs(vel) <= kRestVelTolerance
                       && volume.has_value();
    if (!still) {
        Reset();
        return std::nullopt;
    }

    // Restart the window if pose or CW volume drifted from where it began
    if (count_ > 0
        && (std::abs(pos - anchor_theta_) > kRestPosTolerance
            || std::abs(*volume - anchor_volume_) > kRestVolTolerance)) {
        Reset();
    }

    if (count_ == 0) {
        anchor_theta_ = pos;
        anchor_volume_ = *volume;
    } else {
        t_elapsed_s_ += dt;
    }

    sum_theta_ += pos;
    sum_torque_ += torque_actuator;
    sum_volume_ += *volume;
    ++count_;

    if (t_elapsed_s_ >= kRestWindowTime && count_ >= 2) {
        Motion::RestSample sample;
        sample.theta = sum_theta_ / count_;
        sample.torque_actuator = sum_torque_ / count_;
        sample.volume = sum_volume_ / count_;
        Reset();
        return sample;
    }
    return std::nullopt;
}

//------------------------------------------------------------------------------
// !Class Management
//------------------------------------------------------------------------------

/**
 * @brief Delegating constructor. Uses this file's model constants.
 *
 * @param logger Logger for this motion controller (taken over)
 * @param cw_capacity CW capacity (L)
 * @param torque_comp_lower_bound ATC "soft" limit (Nm)
 * @param torque_comp_upper_bound ATC "hard" limit (Nm)
 * @param torque_comp_slow_rate Trajectory playback rate between ATC limits
 */
Libra2MotionController::Libra2MotionController(
    std::unique_ptr<Logger> logger, const double& cw_capacity,
    const double& torque_comp_lower_bound,
    const double& torque_comp_upper_bound, const double& torque_comp_slow_rate)
    : Libra2MotionController(std::move(logger), kCwPivotDist, kCwPivotSlope,
                             kCwHangOffset, cw_capacity,
                             kDefaultFrictionCoulomb, kDefaultFrictionViscous,
                             kArmInertia, torque_comp_lower_bound,
                             torque_comp_upper_bound, torque_comp_slow_rate) {}

/**
 * @brief Standard constructor.
 *
 * @param logger Logger for this motion controller (taken over)
 * @param cw_pivot_dist CW pivot distance at 0 L, A (m); 0 = not measured
 * @param cw_pivot_slope Change in CW pivot distance per liter, B (m/L)
 * @param cw_hang_offset CW hang-point offset normal to arm, from pitch joint,
 *                       q_P (m)
 * @param cw_capacity CW capacity (L)
 * @param friction_coulomb Coulomb friction torque, τ_c (Nm)
 * @param friction_viscous Viscous friction coefficient, b (Nm·s/rad)
 * @param arm_inertia Arm's moment of inertia about pitch joint (kg·m²)
 * @param torque_comp_lower_bound ATC "soft" limit (Nm)
 * @param torque_comp_upper_bound ATC "hard" limit (Nm)
 * @param torque_comp_slow_rate Trajectory playback rate between ATC limits
 *
 * @note The CW's share of the inertia comes from the CW model and flow rate.
 */
Libra2MotionController::Libra2MotionController(
    std::unique_ptr<Logger> logger, const double& cw_pivot_dist,
    const double& cw_pivot_slope, const double& cw_hang_offset,
    const double& cw_capacity, const double& friction_coulomb,
    const double& friction_viscous, const double& arm_inertia,
    const double& torque_comp_lower_bound,
    const double& torque_comp_upper_bound, const double& torque_comp_slow_rate)
    : AbstractMotionController(std::move(logger),
                               Joint::GetHebiStrings().size()),
      cw_model_(cw_pivot_dist, cw_pivot_slope, cw_hang_offset, cw_capacity),
      friction_coulomb_(friction_coulomb),
      friction_viscous_(friction_viscous),
      arm_inertia_(arm_inertia),
      torque_comp_lower_bound_(torque_comp_lower_bound),
      torque_comp_upper_bound_(torque_comp_upper_bound),
      torque_comp_slow_rate_(torque_comp_slow_rate) {
    if (!cw_model_.IsValid()) {
        logger_->Warn("CW model invalid: " + cw_model_.GetError()
                      + " (calibration and feedforward are unavailable)");
    }
}

//------------------------------------------------------------------------------
// !Settings & Arm Model
//------------------------------------------------------------------------------

/**
 * @brief Selects tandem or CW-primary motion.
 *
 * @param mode Mode to use from next target on
 *
 * @note Returns false if CW-primary is refused (needs arm and CW models, and
 *       no move in progress). Switching to tandem is always accepted; mid-move
 *       it hands off to the actuator so the arm is never left free.
 */
bool Libra2MotionController::SetMotionMode(const Motion::MotionMode& mode) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (mode == Motion::MotionMode::kCwPrimary
        && !(calibrated_ && cw_model_.IsValid())) {
        logger_->Warn("CW-primary mode needs a calibrated arm model and a "
                      "valid CW model; staying in the current mode");
        return false;
    }
    if (mode == Motion::MotionMode::kCwPrimary && IsMovingLocked()) {
        logger_->Warn("Can't switch to CW-primary while the arm is moving; "
                      "staying in the current mode");
        return false;
    }

    if (cw_phase_ == CwPhase::kCwMoving) {
        logger_->Warn("Left CW-primary while the CW was moving the arm; "
                      "handing off to the actuator");
        cw_phase_ = CwPhase::kIdle;
        cw_assist_done_ = true;
        if (target_pos_) {
            pending_move_ = (*target_pos_)[kPitchIdx];
        }
    } else if (!IsMovingLocked()) {
        // A move in progress keeps its CW state until the next target
        cw_phase_ = CwPhase::kIdle;
        cw_assist_done_ = false;
    }

    mode_ = mode;
    logger_->Info(
        std::string("Motion mode: ")
        + (mode == Motion::MotionMode::kTandem ? "tandem" : "CW-primary"));
    return true;
}

/**
 * @brief Gets the selected motion mode.
 */
Motion::MotionMode Libra2MotionController::GetMotionMode() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return mode_;
}

/**
 * @brief Whether the arm is moving or about to: a trajectory is running, the
 *        CW is moving the arm, a move is queued, or a calibration is running.
 *
 * @note Trajectory state is as of the last `Update()`.
 */
bool Libra2MotionController::IsMoving() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return IsMovingLocked();
}

/**
 * @brief Stores latest CW state (from WaterController).
 *
 * @param volume CW volume, V (L)
 * @param flow Net CW flow rate, V̇ (L/s); positive = filling
 */
void Libra2MotionController::SetCwState(const double& volume,
                                        const double& flow) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!std::isfinite(volume) || volume < 0.0 || !std::isfinite(flow)) {
        logger_->Warn("Ignoring invalid CW state: " + Format(volume) + " L, "
                      + Format(flow) + " L/s");
        return;
    }
    cw_vol_ = volume;
    cw_flow_ = flow;
}

/**
 * @brief Enables or disables automatic torque compensation (torque throttle
 *        and, if uncalibrated, reactive CW command).
 *
 * @param enabled Whether to enable
 */
void Libra2MotionController::EnableTorqueComp(const bool& enabled) {
    std::lock_guard<std::mutex> lock(mutex_);
    atc_en_ = enabled;
    if (!atc_en_) {
        movement_en_ = true;  // "manual" mode: movement is always allowed
    }
    logger_->Info("Automatic torque compensation "
                  + std::string(enabled ? "enabled" : "disabled"));
}

/**
 * @brief Enables or disables the inertia terms of the torque feedforward,
 *        e.g., to compare a move with and without them.
 *
 * @param enabled Whether to include them
 */
void Libra2MotionController::EnableInertiaFeedforward(const bool& enabled) {
    std::lock_guard<std::mutex> lock(mutex_);
    inertia_ff_en_ = enabled;
    logger_->Info("Inertia feedforward "
                  + std::string(enabled ? "enabled" : "disabled"));
}

/**
 * @brief Sets the throttle's soft and hard torque limits.
 *
 * @param lower_bound Soft limit (Nm); playback slows at or above it
 * @param upper_bound Hard limit (Nm); playback pauses above it
 *
 * @note Rejects invalid bounds (need 0 <= lower < upper) and returns false.
 */
bool Libra2MotionController::SetTorqueCompBounds(const double& lower_bound,
                                                 const double& upper_bound) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!(lower_bound >= 0.0) || !(lower_bound < upper_bound)) {
        logger_->Warn("Ignoring invalid torque compensation bounds: lower="
                      + Format(lower_bound)
                      + " Nm, upper=" + Format(upper_bound) + " Nm");
        return false;
    }
    torque_comp_lower_bound_ = lower_bound;
    torque_comp_upper_bound_ = upper_bound;
    logger_->Info("Torque compensation bounds updated: lower="
                  + Format(lower_bound) + " Nm, upper=" + Format(upper_bound)
                  + " Nm");
    return true;
}

/**
 * @brief Sets the CW-primary hand-off band.
 *
 * @param band Band around target angle (rad); inside it, CW stops and
 *             actuator takes over
 *
 * @note Rejects a non-positive band and returns false.
 */
bool Libra2MotionController::SetHandoffBand(const double& band) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!(band > 0.0) || !std::isfinite(band)) {
        logger_->Warn("Ignoring invalid hand-off band: " + Format(band)
                      + " rad");
        return false;
    }
    handoff_band_ = band;
    logger_->Info("Hand-off band updated: " + Format(band) + " rad");
    return true;
}

/**
 * @brief Sets the arm model directly.
 *
 * @param arm_level_torque Arm gravity torque at level, τ_g1,0 (Nm)
 * @param arm_hang_torque Arm hang torque, m_arm·h_1·g (Nm)
 *
 * @note No raw samples are kept, so a saved record of it can't be recomputed
 *       if the CW model changes. Use `LoadCalibrationRecord()` for saved
 *       calibrations.
 */
void Libra2MotionController::SetArmModel(const double& arm_level_torque,
                                         const double& arm_hang_torque) {
    std::lock_guard<std::mutex> lock(mutex_);
    arm_level_torque_ = arm_level_torque;
    arm_hang_torque_ = arm_hang_torque;
    calibrated_ = true;
    arm_source_ = "set";
    arm_cw_params_ = cw_model_.GetParams();
    arm_samples_.clear();
    logger_->Info("Arm model set: arm_level_torque=" + Format(arm_level_torque)
                  + " Nm, arm_hang_torque=" + Format(arm_hang_torque) + " Nm");
    CheckStability(arm_hang_torque_);
}

/**
 * @brief Forgets the arm model, disabling feedforward, the predictive CW
 *        command, and CW-primary mode.
 */
void Libra2MotionController::ClearArmModel() {
    std::lock_guard<std::mutex> lock(mutex_);
    arm_level_torque_ = 0.0;
    arm_hang_torque_ = 0.0;
    calibrated_ = false;
    arm_source_.clear();
    arm_samples_.clear();
    mode_ = Motion::MotionMode::kTandem;  // CW-primary needs the model
    cw_phase_ = CwPhase::kIdle;
    logger_->Info("Arm model cleared; feedforward and predictive CW disabled");
}

/**
 * @brief Whether an arm model is available (calibrated, loaded, or set via
 *        `SetArmModel()`).
 */
bool Libra2MotionController::IsCalibrated() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return calibrated_;
}

/**
 * @brief Gets arm gravity torque at level, τ_g1,0 (Nm).
 */
double Libra2MotionController::GetArmLevelTorque() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return arm_level_torque_;
}

/**
 * @brief Gets arm hang torque, m_arm·h_1·g (Nm).
 */
double Libra2MotionController::GetArmHangTorque() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return arm_hang_torque_;
}

/**
 * @brief Net gravity torque (Nm) about pitch joint for a given angle and CW
 *        mass.
 *
 * @param theta Pitch angle, θ (rad)
 * @param cw_mass CW mass, m_cw (kg)
 *
 * @note Doesn't lock, since `Update()` calls it while holding the lock. From
 *       outside, only call it while the motion controller isn't running.
 *
 * @see Libra2Model::NetGravTorque
 */
double Libra2MotionController::ComputeNetGravTorque(
    const double& theta, const double& cw_mass) const {
    return Libra2Model::NetGravTorque(arm_level_torque_, arm_hang_torque_,
                                      cw_model_.Moment(cw_mass),
                                      cw_model_.HangMoment(cw_mass), kGrav,
                                      theta);
}

//------------------------------------------------------------------------------
// !Calibration Commands
//------------------------------------------------------------------------------

/**
 * @brief Starts the level calibration (arm must already be level and at rest).
 *
 * @note Refused (returns false) if a calibration is already running or the CW
 *       model is invalid.
 *
 * @note Uses Eq. 34 (`H_Holding-Torque-at-any-Angle.jpg`) at the measured
 *       angle (near 0), which reduces to Eq. 31 (`G_Estimating-State.jpg`):
 *         τ_g1,0 = τ_meas(0) − m_cw·g·r_P
 */
bool Libra2MotionController::StartLevelCalibration() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (Motion::IsCalibrationRunning(status_)) {
        logger_->Warn("Calibration already running; ignoring level request");
        return false;
    }
    if (!cw_model_.IsValid()) {
        logger_->Error("Can't calibrate: CW model invalid ("
                       + cw_model_.GetError() + ")");
        return false;
    }

    two_angle_ = false;
    BeginStage(Motion::CalibrationStatus::kSamplingLevel);
    logger_->Info("Level calibration started (arm must be level and at rest)");
    return true;
}

/**
 * @brief Starts the two-angle calibration; the motion controller requests the
 *        moves via `Libra2Command::move_to`.
 *
 * @param angle_a First angle, θ_a (rad, joint space)
 * @param angle_b Second angle, θ_b (rad, joint space)
 *
 * @note Refused (returns false) if a calibration is already running, the CW
 *       model is invalid, or the angles are out of range or too close.
 *
 * @note From Eq. 35c (`H_Holding-Torque-at-any-Angle.jpg`); see
 *       `SolveTwoAngle()`:
 *         τ_g1,0 = (τ_g1(θ_a)·sin θ_b − τ_g1(θ_b)·sin θ_a) / sin(θ_b − θ_a)
 */
bool Libra2MotionController::StartTwoAngleCalibration(const double& angle_a,
                                                      const double& angle_b) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (Motion::IsCalibrationRunning(status_)) {
        logger_->Warn("Calibration already running; ignoring two-angle "
                      "request");
        return false;
    }
    if (!cw_model_.IsValid()) {
        logger_->Error("Can't calibrate: CW model invalid ("
                       + cw_model_.GetError() + ")");
        return false;
    }
    if (!std::isfinite(angle_a) || !std::isfinite(angle_b)
        || std::abs(angle_a) > Motion::kMaxCalibrationAngle
        || std::abs(angle_b) > Motion::kMaxCalibrationAngle
        || std::abs(angle_b - angle_a) < Motion::kMinAngleSeparation) {
        logger_->Warn("Two-angle calibration rejected: need |angle| <= "
                      + Format(Motion::kMaxCalibrationAngle) + " rad and "
                      + "|b - a| >= " + Format(Motion::kMinAngleSeparation)
                      + " rad (got a=" + Format(angle_a)
                      + ", b=" + Format(angle_b) + ")");
        return false;
    }

    two_angle_ = true;
    angle_a_ = angle_a;
    angle_b_ = angle_b;
    BeginStage(Motion::CalibrationStatus::kMovingToA);
    logger_->Info("Two-angle calibration started: a=" + Format(angle_a)
                  + " rad, b=" + Format(angle_b) + " rad");
    return true;
}

/**
 * @brief Starts the friction calibration: up/down sweeps at several constant
 *        speeds over a window, requested via `Libra2Command::sweep`.
 *
 * @param angle_a One end of the window (rad, joint space)
 * @param angle_b Other end of the window (rad, joint space)
 * @param max_speed Caller's speed limit (rad/s); sweep speeds are fractions
 *                  of it (`kFrictionSpeedFractions`)
 *
 * @note Refused (returns false) if a calibration is already running, the CW
 *       volume is unknown, or the window is out of range, too short, or too
 *       slow to sweep within `kMoveTimeout`. Needs no arm or CW model: gravity
 *       cancels between the up and down sweeps.
 *
 * @note From E8 (`FINDING_ACTUATOR_FRICTION.md`); see `FitFrictionLine()`:
 *         (τ_up − τ_down) / 2 = b·v + τ_c
 */
bool Libra2MotionController::StartFrictionCalibration(const double& angle_a,
                                                      const double& angle_b,
                                                      const double& max_speed) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (Motion::IsCalibrationRunning(status_)) {
        logger_->Warn("Calibration already running; ignoring friction request");
        return false;
    }
    if (!cw_vol_) {
        logger_->Warn("Friction calibration rejected: CW volume unknown "
                      "(needed to check that it stays constant)");
        return false;
    }
    if (!(max_speed > 0.0) || !std::isfinite(max_speed)) {
        logger_->Error("Friction calibration rejected: invalid max speed "
                       + Format(max_speed) + " rad/s");
        return false;
    }

    const double lo = std::min(angle_a, angle_b);
    const double hi = std::max(angle_a, angle_b);
    if (!std::isfinite(lo) || !std::isfinite(hi)
        || std::abs(lo) > Motion::kMaxCalibrationAngle
        || std::abs(hi) > Motion::kMaxCalibrationAngle
        || hi - lo < Motion::kFrictionMinWindow) {
        logger_->Warn("Friction calibration rejected: need |angle| <= "
                      + Format(Motion::kMaxCalibrationAngle) + " rad and "
                      + "|b - a| >= " + Format(Motion::kFrictionMinWindow)
                      + " rad (got a=" + Format(angle_a)
                      + ", b=" + Format(angle_b) + ")");
        return false;
    }

    // Slowest sweep (ramps average half speed) must fit in one move stage
    const double slowest = max_speed * kFrictionSpeedFractions.front();
    const double t_slowest_s = (hi - lo + 2.0 * kFrictionRampDist) / slowest;
    if (t_slowest_s > kMoveTimeout) {
        logger_->Warn("Friction calibration rejected: slowest sweep takes "
                      + Format(t_slowest_s) + " s (limit "
                      + Format(kMoveTimeout) + " s); use a smaller window");
        return false;
    }

    friction_run_ = FrictionRun();
    friction_run_.angle_lo = lo;
    friction_run_.angle_hi = hi;
    friction_run_.max_speed = max_speed;
    friction_run_.volume = *cw_vol_;

    two_angle_ = false;
    BeginStage(Motion::CalibrationStatus::kFrictionMovingToStart);
    logger_->Info("Friction calibration started: window " + Format(lo) + " to "
                  + Format(hi) + " rad, "
                  + std::to_string(kFrictionSpeedFractions.size())
                  + " speeds up to " + Format(max_speed)
                  + " rad/s (CW stays idle; aborts above "
                  + Format(torque_comp_upper_bound_) + " Nm)");
    return true;
}

/**
 * @brief Cancels a running calibration (no effect otherwise).
 */
void Libra2MotionController::CancelCalibration() {
    std::lock_guard<std::mutex> lock(mutex_);
    CancelCalibrationLocked();
}

/**
 * @brief Gets calibration progress.
 */
Motion::CalibrationStatus Libra2MotionController::GetCalibrationStatus() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return status_;
}

/**
 * @brief Gets how the last calibration ended (result, failure reason, or
 *        cancellation), as logged; empty until one has ended.
 */
std::string Libra2MotionController::GetCalibrationMessage() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return calibration_message_;
}

//------------------------------------------------------------------------------
// !Calibration Record
//------------------------------------------------------------------------------

/**
 * @brief Gets the current arm model and friction result, with the raw data
 *        behind them, for saving.
 *
 * @note File metadata (`saved_at`, `extension`, `note`) is left empty.
 */
Motion::CalibrationRecord Libra2MotionController::GetCalibrationRecord() const {
    std::lock_guard<std::mutex> lock(mutex_);
    Motion::CalibrationRecord record;
    record.cw_model = cw_model_.GetParams();
    record.arm_inertia = arm_inertia_;

    if (calibrated_) {
        Motion::ArmModelRecord arm;
        arm.source = arm_source_;
        arm.level_torque = arm_level_torque_;
        arm.hang_torque = arm_hang_torque_;
        arm.cw_model = arm_cw_params_;
        arm.samples = arm_samples_;
        record.arm_model = arm;
    }
    record.friction = friction_result_;
    return record;
}

/**
 * @brief Applies a saved arm model and friction result.
 *
 * @param record Saved calibration
 *
 * @note Returns false (nothing applied) while the arm is moving or calibrating,
 *       or if the record holds neither.
 *
 * @note If the CW model changed since the arm model was made, the arm model is
 *       recomputed from its raw samples with the current CW model. Without
 *       samples, the saved values are used as-is (with a warning).
 */
bool Libra2MotionController::LoadCalibrationRecord(
    const Motion::CalibrationRecord& record) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (IsMovingLocked()) {
        logger_->Warn("Can't load a calibration while the arm is moving or "
                      "calibrating");
        return false;
    }
    if (!record.arm_model && !record.friction) {
        logger_->Warn("Calibration record has no arm model or friction "
                      "result; nothing loaded");
        return false;
    }

    if (record.arm_model) {
        const Motion::ArmModelRecord& arm = *record.arm_model;
        double level = arm.level_torque;
        double hang_torque = arm.hang_torque;
        Motion::CwModelParams params = arm.cw_model;

        if (!Motion::IsSameCwModel(arm.cw_model, cw_model_.GetParams())) {
            if (RecomputeArmModel(arm, level, hang_torque)) {
                params = cw_model_.GetParams();
                logger_->Info("CW model changed since this calibration; arm "
                              "model recomputed from its raw samples (saved: "
                              "arm_level_torque="
                              + Format(arm.level_torque)
                              + " Nm, arm_hang_torque="
                              + Format(arm.hang_torque) + " Nm)");
            } else {
                logger_->Warn("CW model changed since this calibration, but "
                              "its arm model can't be recomputed (no raw "
                              "samples, or CW model invalid); using the "
                              "saved values as-is");
            }
        }

        logger_->Info("Arm model loaded: arm_level_torque "
                      + Format(arm_level_torque_) + " -> " + Format(level)
                      + " Nm, arm_hang_torque " + Format(arm_hang_torque_)
                      + " -> " + Format(hang_torque) + " Nm (" + arm.source
                      + ")");
        arm_level_torque_ = level;
        arm_hang_torque_ = hang_torque;
        calibrated_ = true;
        arm_source_ = arm.source;
        arm_cw_params_ = params;
        arm_samples_ = arm.samples;
        CheckStability(arm_hang_torque_);
    }

    if (record.friction) {
        logger_->Info("Friction loaded: tau_c " + Format(friction_coulomb_)
                      + " -> " + Format(record.friction->coulomb) + " Nm, b "
                      + Format(friction_viscous_) + " -> "
                      + Format(record.friction->viscous) + " Nm*s/rad");
        friction_coulomb_ = record.friction->coulomb;
        friction_viscous_ = record.friction->viscous;
        friction_result_ = record.friction;
    }
    return true;
}

//------------------------------------------------------------------------------
// !Control Cycle
//------------------------------------------------------------------------------

/**
 * @brief Torque throttle with hysteresis (as in LIBRA-I's
 *        `CheckTorqueControl`): slows or pauses the trajectory and picks the
 *        CW direction.
 *
 * @param torque_magnitude |Measured actuator torque| (Nm)
 * @param direction CW direction that relieves the actuator
 * @param braking Whether actuator torque opposes travel (CW leads)
 *
 * @note Result's CW command is none when there's nothing to report.
 *
 * @note Slowing the trajectory only helps while the actuator lifts the arm.
 *       While it brakes, slowing would raise the torque, so the soft limit
 *       keeps full speed and only the CW reacts. The hard limit always stops.
 */
Libra2MotionController::AtcResult Libra2MotionController::UpdateTorqueComp(
    const double& torque_magnitude, const Motion::CwCommand& direction,
    const bool& braking) {
    AtcResult result;

    if (!atc_en_) {
        movement_en_ = true;
        return result;  // defaults: full speed, no report
    }

    bool in_slow_band = false;

    if (torque_magnitude > torque_comp_upper_bound_) {
        // Hard limit: stop movement first, then report the direction on the
        // following cycles (same order as LIBRA-I)
        if (movement_en_) {
            movement_en_ = false;

            logger_->Info("Movement disabled due to high torque ("
                          + Format(torque_magnitude) + " Nm > "
                          + Format(torque_comp_upper_bound_) + " Nm)");
        } else {
            result.cw_command = direction;
        }

    } else if (torque_magnitude >= torque_comp_lower_bound_) {
        // Soft limit: keep reporting the direction and slow the trajectory
        // (unless braking)
        result.cw_command = direction;
        in_slow_band = !braking;

    } else {
        // Acceptable torque: stop balancing and re-enable movement
        result.cw_command = Motion::CwCommand::kIdle;
        if (!movement_en_) {
            movement_en_ = true;

            logger_->Info("Movement re-enabled (" + Format(torque_magnitude)
                          + " Nm < " + Format(torque_comp_lower_bound_)
                          + " Nm)");
        }
    }

    if (!movement_en_) {
        result.playback_rate = 0.0;
    } else {
        result.playback_rate = in_slow_band ? torque_comp_slow_rate_ : 1.0;
    }
    return result;
}

/**
 * @brief Predictive CW command: fill or drain toward the CW mass that balances
 *        the arm at target angle.
 *
 * @param theta_tgt Target angle, θ_tgt (rad)
 * @param cw_mass Current CW mass, m_cw (kg)
 * @param[out] cw_mass_tgt If given, set to balancing CW mass,
 *                         m_cw,bal(θ_tgt) (kg)
 *
 * @note Returns none if balance mass is undefined at this angle.
 *
 * @note From Eqs. 38 and 40a (`I_Controller.jpg`), with Eq. 28
 *       (`G_Estimating-State.jpg`) to convert mass to volume (m_cw,bal from
 *       `BalanceCwMoment()`):
 *         Δm_tgt = m_cw,bal(θ_tgt) − m_cw
 */
std::optional<Motion::CwCommand> Libra2MotionController::PredictiveCwCommand(
    const double& theta_tgt, const double& cw_mass, double* cw_mass_tgt) const {
    // Eq. 38 -> target mass (clamped to what the CW can hold)
    const auto moment_bal = Libra2Model::BalanceCwMoment(arm_level_torque_,
                                                         arm_hang_torque_,
                                                         kGrav, theta_tgt);
    if (!moment_bal) {
        return std::nullopt;
    }
    const auto mass_tgt = cw_model_.MassForMoment(*moment_bal, theta_tgt);
    if (!mass_tgt) {
        return std::nullopt;
    }
    if (cw_mass_tgt != nullptr) {
        *cw_mass_tgt = *mass_tgt;
    }

    // Eq. 40a
    const double diff = *mass_tgt - cw_mass;
    if (std::abs(diff) <= kCwVolumeTolerance * kWaterDensity) {
        return Motion::CwCommand::kIdle;
    }

    // TODO: if valve latency makes the CW overshoot, stop early by latency·V̇
    return (diff > 0.0) ? Motion::CwCommand::kFill : Motion::CwCommand::kDrain;
}

/**
 * @brief One CW-primary cycle: leaves the arm free so the CW moves it until the
 *        volume OR angle criterion is met.
 *
 * @param theta Measured angle, θ (rad)
 * @param theta_tgt Target angle, θ_tgt (rad)
 * @param[in,out] command Command to fill while the arm stays free
 *
 * @note Returns true while the arm stays free, and false at hand-off (actuator
 *       takes over and a move is requested).
 *
 * @note After hand-off, the predictive CW command stays off until the next
 *       target, so it can't refill the CW while the actuator finishes the
 *       move. The reactive (ATC) command still trims residual torque.
 */
bool Libra2MotionController::RunCwPrimary(const double& theta,
                                          const double& theta_tgt,
                                          Motion::Libra2Command& command) {
    double mass_tgt = 0.0;
    const auto cw = PredictiveCwCommand(theta_tgt, *cw_mass_, &mass_tgt);
    if (!cw) {
        logger_->Warn("CW-primary: target mass undefined at this angle; "
                      "handing off to the actuator");
        cw_phase_ = CwPhase::kIdle;
        cw_assist_done_ = true;
        pending_move_ = theta_tgt;
        return false;
    }

    const bool volume_reached = (*cw == Motion::CwCommand::kIdle);
    const bool angle_reached = std::abs(theta - theta_tgt) <= handoff_band_;

    if (volume_reached || angle_reached) {
        // Log model error (the criterion that did NOT fire shows it)
        logger_->Info("CW-primary hand-off ("
                      + std::string(volume_reached ? "volume" : "")
                      + std::string(volume_reached && angle_reached ? "+" : "")
                      + std::string(angle_reached ? "angle" : "")
                      + " reached): theta=" + Format(theta) + " rad, target="
                      + Format(theta_tgt) + " rad, angle error="
                      + Format(theta - theta_tgt) + " rad; volume="
                      + Format(*cw_mass_ / kWaterDensity) + " L, target volume="
                      + Format(mass_tgt / kWaterDensity) + " L, volume error="
                      + Format((*cw_mass_ - mass_tgt) / kWaterDensity) + " L");

        cw_phase_ = CwPhase::kIdle;
        cw_assist_done_ = true;
        pending_move_ = theta_tgt;
        return false;
    }

    // Arm stays free (effort only); CW does the moving
    command.mode[kPitchIdx] = Motion::CommandMode::kEffortOnly;
    command.cw_command = cw;
    command.playback_rate = 1.0;
    movement_en_ = true;
    return true;
}

/**
 * @brief Runs one control cycle: what to do with the actuator and CW.
 *
 * @param state Measurements and previous cycle's reference
 *
 * @note If anything CW-primary needs is lost while the arm is free (model, CW
 *       volume, target, or ATC), the actuator takes over right away rather
 *       than leaving the arm uncontrolled.
 */
Motion::Libra2Command Libra2MotionController::Update(
    const Motion::MotionState& state) {
    std::lock_guard<std::mutex> lock(mutex_);
    Motion::Libra2Command command(n_joints_);

    if (!IsValid(state) || n_joints_ <= kPitchIdx) {
        if (!state_warned_) {
            logger_->Error("MotionState arrays must each have "
                           + std::to_string(n_joints_) + " entries");
            state_warned_ = true;
        }
        return command;
    }

    const double theta = state.pos[kPitchIdx];
    const double vel = state.vel[kPitchIdx];
    const double torque = state.torque_actuator[kPitchIdx];
    trajectory_active_ = state.trajectory_active;

    // Eq. 28: CW mass from latest volume (none until one arrives)
    cw_mass_ = cw_vol_ ? std::optional<double>(Libra2Model::CwMass(*cw_vol_))
                       : std::nullopt;

    // Eq. 15: inertia and its rate, with the CW's share (ṁ_cw = ρ_water·V̇)
    if (cw_mass_ && cw_model_.IsValid()) {
        inertia_ = arm_inertia_ + cw_model_.Inertia(*cw_mass_);
        inertia_rate_ = cw_model_.InertiaSlope(*cw_mass_) * kWaterDensity
                        * cw_flow_;
    } else {
        inertia_ = arm_inertia_;
        inertia_rate_ = 0.0;
    }

    const bool calibrating = Motion::IsCalibrationRunning(status_);
    const bool model_ready = calibrated_ && cw_model_.IsValid()
                             && cw_mass_.has_value();
    std::optional<double> target;
    if (target_pos_) {
        target = (*target_pos_)[kPitchIdx];
    }

    // CW-primary: arm is left free while CW moves it
    bool arm_free = false;
    if (mode_ == Motion::MotionMode::kCwPrimary
        && cw_phase_ == CwPhase::kCwMoving) {
        if (!model_ready || !target || calibrating || !atc_en_) {
            logger_->Warn("CW-primary: model, CW volume, target, or ATC "
                          "unavailable; handing off to the actuator");
            cw_phase_ = CwPhase::kIdle;
            cw_assist_done_ = true;
            if (target) {
                pending_move_ = *target;
            }
        } else {
            arm_free = RunCwPrimary(theta, *target, command);
        }
    }

    if (!arm_free && IsFrictionStage(status_)) {
        // Friction sweep: no throttle or CW command (aborts at hard limit)
        command.playback_rate = 1.0;
        command.cw_command = Motion::CwCommand::kIdle;
        RunFrictionCalibration(state, theta, vel, torque);
    } else if (!arm_free) {
        // Tandem/holding: ATC throttle; filling relieves positive torque, and
        // the actuator brakes when its torque opposes travel
        const Motion::CwCommand direction = (torque > 0.0)
                                                ? Motion::CwCommand::kFill
                                                : Motion::CwCommand::kDrain;
        const bool braking = target && (torque * (*target - theta) < 0.0);
        const AtcResult atc = UpdateTorqueComp(std::abs(torque), direction,
                                               braking);
        command.playback_rate = atc.playback_rate;
        command.cw_command = atc.cw_command;  // reactive (LIBRA-I style)

        if (calibrating) {
            // Feedforward off and CW reactive while calibrating
            RunCalibration(state, theta, vel, torque);
        } else {
            // Predictive CW replaces reactive, except after a hand-off
            if (model_ready && target && !cw_assist_done_) {
                const auto predicted = PredictiveCwCommand(*target, *cw_mass_,
                                                           nullptr);
                if (predicted) {
                    command.cw_command = predicted;
                }
            }

            // Eqs. 36-37 (no clamping)
            if (model_ready) {
                const double torque_ext_g = ComputeNetGravTorque(theta,
                                                                 *cw_mass_);
                const double inertia = inertia_ff_en_ ? inertia_ : 0.0;
                const double inertia_rate = inertia_ff_en_ ? inertia_rate_
                                                           : 0.0;
                command.torque_actuator_cmd[kPitchIdx] =
                    Libra2Model::TorqueCommand(inertia, inertia_rate,
                                               friction_viscous_,
                                               friction_coulomb_,
                                               state.ref_acc[kPitchIdx],
                                               state.ref_vel[kPitchIdx],
                                               torque_ext_g);
            }
        }
    }

    // One-shot requests (stop before move, so a new move isn't cancelled)
    if (pending_stop_) {
        command.stop_trajectory = true;
        pending_stop_ = false;
    }
    if (pending_move_) {
        std::vector<double> move = state.pos;
        move[kPitchIdx] = *pending_move_;
        command.move_to = move;
        pending_move_.reset();
    }
    if (pending_sweep_) {
        command.sweep = pending_sweep_;
        pending_sweep_.reset();
    }

    ComputeDiagnostics(theta, target, command.diagnostics);
    return command;
}

/**
 * @brief Computes log-only model values: CW mass, net gravity torques (now and
 *        at target), and target CW mass.
 *
 * @param theta Measured angle, θ (rad)
 * @param theta_tgt Target angle, θ_tgt (rad), if any
 * @param[out] diagnostics Values to fill; uncomputable entries stay empty
 *
 * @see Libra2Model::CwMass Libra2Model::NetGravTorque
 *      Libra2Model::BalanceCwMoment Libra2Model::TargetNetGravTorque
 */
void Libra2MotionController::ComputeDiagnostics(
    const double& theta, const std::optional<double>& theta_tgt,
    Motion::Libra2Diagnostics& diagnostics) const {
    diagnostics.cw_mass = cw_mass_;
    if (!calibrated_ || !cw_model_.IsValid()) {
        return;
    }

    if (cw_mass_) {
        diagnostics.torque_ext_g = ComputeNetGravTorque(theta, *cw_mass_);
    }

    // Eqs. 38-40
    if (theta_tgt) {
        const auto moment_bal = Libra2Model::BalanceCwMoment(arm_level_torque_,
                                                             arm_hang_torque_,
                                                             kGrav, *theta_tgt);
        const auto mass_tgt = moment_bal ? cw_model_.MassForMoment(*moment_bal,
                                                                   *theta_tgt)
                                         : std::nullopt;
        if (mass_tgt) {
            diagnostics.cw_mass_tgt = *mass_tgt;
            if (cw_mass_) {
                diagnostics.cw_mass_change = *mass_tgt - *cw_mass_;
                diagnostics.torque_ext_g_tgt = Libra2Model::TargetNetGravTorque(
                    kGrav, *theta_tgt,
                    cw_model_.EffectiveMoment(*cw_mass_, *theta_tgt),
                    *moment_bal);
            }
        }
    }
}

//------------------------------------------------------------------------------
// !Hooks
//------------------------------------------------------------------------------

/**
 * @brief New target: cancels any calibration move, then either requests the
 *        actuator move (tandem) or lets the CW start moving the arm
 *        (CW-primary).
 *
 * @note HebiThread starts every LIBRA-II trajectory from `move_to`, so the
 *       choice of how to reach a target is made here only.
 */
void Libra2MotionController::OnTargetChanged() {
    // A manual target overrides any calibration move
    CancelCalibrationLocked();

    // Mode is read here, so a mode change applies from the next target
    cw_assist_done_ = false;
    if (mode_ == Motion::MotionMode::kCwPrimary) {
        cw_phase_ = CwPhase::kCwMoving;
        pending_move_.reset();  // hand-off requests the move
    } else {
        cw_phase_ = CwPhase::kIdle;
        pending_move_ = (*target_pos_)[kPitchIdx];
    }
}

/**
 * @brief Target dropped: cancels calibration and CW assistance.
 */
void Libra2MotionController::OnStop() {
    CancelCalibrationLocked();
    cw_phase_ = CwPhase::kIdle;
    cw_assist_done_ = false;
    pending_move_.reset();
}

/**
 * @brief Full runtime reset (on disconnect): like `OnStop()`, plus ATC and
 *        warning latches. Keeps settings, arm model, and friction.
 */
void Libra2MotionController::OnReset() {
    CancelCalibrationLocked();
    cw_phase_ = CwPhase::kIdle;
    cw_assist_done_ = false;
    pending_move_.reset();
    pending_stop_ = false;  // nothing left to stop
    trajectory_active_ = false;
    movement_en_ = true;
    state_warned_ = false;
}

//------------------------------------------------------------------------------
// !Model Calibration Helpers
//------------------------------------------------------------------------------

/**
 * @brief Cancels a running calibration (`mutex_` must already be held).
 *
 * @note A cancelled friction sweep also requests a stop, since its trajectory
 *       would otherwise run to the end of the window.
 */
void Libra2MotionController::CancelCalibrationLocked() {
    if (Motion::IsCalibrationRunning(status_)) {
        if (IsFrictionStage(status_)) {
            pending_stop_ = true;
        }
        status_ = Motion::CalibrationStatus::kIdle;
        pending_move_.reset();
        pending_sweep_.reset();
        sampler_.Reset();
        calibration_message_ = "Calibration cancelled";
        logger_->Info(calibration_message_);
    }
}

/**
 * @brief Same as `IsMoving()` (`mutex_` must already be held).
 */
bool Libra2MotionController::IsMovingLocked() const {
    return trajectory_active_ || (cw_phase_ == CwPhase::kCwMoving)
           || pending_move_.has_value() || pending_sweep_.has_value()
           || Motion::IsCalibrationRunning(status_);
}

/**
 * @brief Enters a calibration stage and, for moving stages, requests the move.
 *
 * @param status Stage to enter
 */
void Libra2MotionController::BeginStage(const Motion::CalibrationStatus& status) {
    status_ = status;
    t_stage_s_ = 0.0;
    sampler_.Reset();

    FrictionRun& run = friction_run_;
    switch (status) {
        case Motion::CalibrationStatus::kMovingToA:
            pending_move_ = angle_a_;
            break;
        case Motion::CalibrationStatus::kMovingToB:
            pending_move_ = angle_b_;
            break;
        case Motion::CalibrationStatus::kFrictionMovingToStart:
            pending_move_ = run.angle_lo;
            break;
        case Motion::CalibrationStatus::kFrictionSweepUp:
        case Motion::CalibrationStatus::kFrictionSweepDown:
            {
                const bool up = (status
                                 == Motion::CalibrationStatus::kFrictionSweepUp);
                Motion::SweepRequest sweep;
                sweep.from = up ? run.angle_lo : run.angle_hi;
                sweep.to = up ? run.angle_hi : run.angle_lo;
                sweep.speed = run.max_speed
                              * kFrictionSpeedFractions.at(run.speed_idx);
                sweep.ramp_dist = kFrictionRampDist;
                pending_sweep_ = sweep;
                run.trajectory_seen = false;

                // Each speed starts with an up sweep and fresh bins
                if (up) {
                    const auto n_bins = static_cast<std::size_t>(
                        std::ceil((run.angle_hi - run.angle_lo
                                   - 2.0 * kFrictionSampleMargin)
                                  / kFrictionBinWidth));
                    run.up_sum.assign(n_bins, 0.0);
                    run.down_sum.assign(n_bins, 0.0);
                    run.up_count.assign(n_bins, 0);
                    run.down_count.assign(n_bins, 0);
                }
                break;
            }
        default:
            break;
    }
}

/**
 * @brief Ends the calibration and logs the outcome.
 *
 * @param success Whether the arm model or friction was updated
 * @param message Outcome (success: the result; failure: the reason)
 */
void Libra2MotionController::FinishCalibration(const bool& success,
                                               const std::string& message) {
    status_ = success ? Motion::CalibrationStatus::kSucceeded
                      : Motion::CalibrationStatus::kFailed;
    pending_move_.reset();
    pending_sweep_.reset();
    sampler_.Reset();
    if (success) {
        calibration_message_ = message;
        logger_->Info(calibration_message_);
    } else {
        calibration_message_ = "Calibration failed: " + message;
        logger_->Error(calibration_message_);
    }
}

/**
 * @brief Converts an averaged rest sample into arm's own gravity torque (Nm).
 *
 * @param sample Averaged measurements
 *
 * @note At rest, measured torque is the opposite of actuator torque, per
 *       Eq. 19 (`D-E_Joint-Dynamics_Balance.jpg`). Eq. 29a
 *       (`G_Estimating-State.jpg`) then removes the CW torque (see
 *       `CwGravTorque()`), with Eq. 28 for CW mass:
 *         τ_meas(θ) = −τ_actuator
 *         τ_g1(θ) = τ_meas(θ) − τ_g2(θ)
 */
double Libra2MotionController::SampleToArmTorque(
    const Motion::RestSample& sample) const {
    const double cw_mass = Libra2Model::CwMass(sample.volume);
    const double cw_torque = Libra2Model::CwGravTorque(cw_model_.Moment(cw_mass),
                                                       cw_model_.HangMoment(
                                                           cw_mass),
                                                       kGrav, sample.theta);

    // tau_meas = -tau_actuator (Eq. 19); then Eq. 29a
    return Libra2Model::ArmGravTorque(-sample.torque_actuator, cw_torque);
}

/**
 * @brief Recomputes a saved arm model from its raw samples with the current
 *        CW model.
 *
 * @param record Saved arm model (one sample = level, two = two-angle)
 * @param[out] arm_level_torque Recomputed τ_g1,0 (Nm)
 * @param[out] arm_hang_torque Recomputed m_arm·h_1·g (Nm); level keeps the
 *                             saved one
 *
 * @note Fails if the CW model is invalid or the samples can't be solved.
 */
bool Libra2MotionController::RecomputeArmModel(
    const Motion::ArmModelRecord& record, double& arm_level_torque,
    double& arm_hang_torque) const {
    if (!cw_model_.IsValid()) {
        return false;
    }

    if (record.samples.size() == 1) {
        // Eq. 34 with the saved arm_hang_torque (as the level calibration did)
        const Motion::RestSample& s = record.samples.front();
        const auto level = Libra2Model::ArmLevelTorque(SampleToArmTorque(s),
                                                       s.theta,
                                                       record.hang_torque);
        if (!level) {
            return false;
        }
        arm_level_torque = *level;
        arm_hang_torque = record.hang_torque;
        return true;
    }

    if (record.samples.size() == 2) {
        // Eq. 35
        const Motion::RestSample& a = record.samples[0];
        const Motion::RestSample& b = record.samples[1];
        return Libra2Model::SolveTwoAngle(SampleToArmTorque(a), a.theta,
                                          SampleToArmTorque(b), b.theta,
                                          arm_level_torque, arm_hang_torque);
    }
    return false;
}

/**
 * @brief Checks whether the arm is stable at every CW volume, and logs the
 *        result.
 *
 * @param arm_hang_torque Arm hang torque, m_arm·h_1·g (Nm)
 *
 * @note Eq. 26c (extended; see `StabilityTorque()`) is linear in m_cw, so
 *       checking empty and full covers every volume.
 */
bool Libra2MotionController::CheckStability(const double& arm_hang_torque) {
    const double cap = cw_model_.GetCapacityMass();
    const double empty = Libra2Model::StabilityTorque(arm_hang_torque,
                                                      cw_model_.HangMoment(0.0),
                                                      kGrav);
    const double full = Libra2Model::StabilityTorque(arm_hang_torque,
                                                     cw_model_.HangMoment(cap),
                                                     kGrav);
    const std::string values = Format(empty) + " Nm empty, " + Format(full)
                               + " Nm full";

    if (std::max(empty, full) < 0.0) {
        logger_->Info("Arm model is stable at all CW volumes");
        logger_->Debug("Stability (S + m_cw*g*q_P < 0, Eq. 26c): " + values);
        return true;
    }

    // Linear in m_cw, so a sign change between empty and full has one crossover
    std::string range = "at every CW volume";
    if ((empty < 0.0) != (full < 0.0)) {
        const double crossover = cap * empty / (empty - full) / kWaterDensity;
        range = std::string(empty < 0.0 ? "above " : "below ")
                + Format(crossover) + " L";
    }
    logger_->Warn("Arm model is unstable " + range
                  + " (S + m_cw*g*q_P >= 0, Eq. 26c): " + values
                  + "; check the calibration");
    return false;
}

/**
 * @brief Advances the running arm calibration (level or two-angle) by one
 *        cycle.
 *
 * @param state Current measurements
 * @param theta Measured angle, θ (rad)
 * @param vel Measured velocity, θ̇ (rad/s)
 * @param torque Measured actuator torque (Nm)
 */
void Libra2MotionController::RunCalibration(const Motion::MotionState& state,
                                            const double& theta,
                                            const double& vel,
                                            const double& torque) {
    t_stage_s_ += state.dt;

    const bool moving_stage = (status_ == Motion::CalibrationStatus::kMovingToA
                               || status_
                                      == Motion::CalibrationStatus::kMovingToB);
    const bool at_a = (status_ == Motion::CalibrationStatus::kMovingToA
                       || status_ == Motion::CalibrationStatus::kSamplingA);
    const double target = at_a ? angle_a_ : angle_b_;

    if (t_stage_s_ > (moving_stage ? kMoveTimeout : kSampleTimeout)) {
        FinishCalibration(false, moving_stage ? "timed out moving to target"
                                              : "timed out waiting for steady "
                                                "pose, torque, and CW volume");
        return;
    }

    if (moving_stage) {
        // "Already there" counts too (zero-length moves start no trajectory)
        if (!state.trajectory_active
            && std::abs(theta - target) <= kReachTolerance
            && std::abs(vel) <= kRestVelTolerance) {
            BeginStage(at_a ? Motion::CalibrationStatus::kSamplingA
                            : Motion::CalibrationStatus::kSamplingB);
        }
        return;
    }

    // Sampling: pose must stay near target (except for level calibration)
    if (status_ != Motion::CalibrationStatus::kSamplingLevel
        && std::abs(theta - target) > 2.0 * kReachTolerance) {
        sampler_.Reset();
        return;
    }

    const auto sample = sampler_.Add(state.dt, theta, vel, torque,
                                     state.trajectory_active, cw_vol_);
    if (!sample) {
        return;
    }
    const double arm_torque = SampleToArmTorque(*sample);

    if (status_ == Motion::CalibrationStatus::kSamplingLevel) {
        if (std::abs(sample->theta) > kMaxLevelAngle) {
            FinishCalibration(false, "arm is not level (theta="
                                         + Format(sample->theta) + " rad)");
            return;
        }
        // Eq. 34 with current arm_hang_torque_ (0 if never calibrated)
        const auto level = Libra2Model::ArmLevelTorque(arm_torque,
                                                       sample->theta,
                                                       arm_hang_torque_);
        if (!level) {
            FinishCalibration(false, "cos(theta) too small");
            return;
        }
        if (!calibrated_) {
            logger_->Warn("arm_hang_torque not calibrated: using "
                          "arm_hang_torque = 0 (run two-angle calibration to "
                          "measure it)");
        }
        arm_level_torque_ = *level;
        calibrated_ = true;
        arm_source_ = "level";
        arm_cw_params_ = cw_model_.GetParams();
        arm_samples_ = {*sample};
        FinishCalibration(true, "Level calibration succeeded: arm_level_torque="
                                    + Format(arm_level_torque_)
                                    + " Nm, arm_hang_torque="
                                    + Format(arm_hang_torque_) + " Nm");
        return;
    }

    if (status_ == Motion::CalibrationStatus::kSamplingA) {
        sample_a_ = *sample;
        BeginStage(Motion::CalibrationStatus::kMovingToB);
        return;
    }

    // kSamplingB: Eq. 35 with MEASURED angles
    double level = 0.0;
    double hang_torque = 0.0;
    if (!Libra2Model::SolveTwoAngle(SampleToArmTorque(sample_a_),
                                    sample_a_.theta, arm_torque, sample->theta,
                                    level, hang_torque)) {
        FinishCalibration(false, "measured angles too close together");
        return;
    }
    arm_level_torque_ = level;
    arm_hang_torque_ = hang_torque;
    calibrated_ = true;
    arm_source_ = "two-angle";
    arm_cw_params_ = cw_model_.GetParams();
    arm_samples_ = {sample_a_, *sample};
    const bool stable = CheckStability(hang_torque);
    FinishCalibration(true,
                      "Two-angle calibration succeeded: arm_level_torque="
                          + Format(arm_level_torque_)
                          + " Nm, arm_hang_torque=" + Format(arm_hang_torque_)
                          + " Nm" + (stable ? "" : " (UNSTABLE; see log)"));
}

//------------------------------------------------------------------------------
// !Friction Calibration Helpers
//------------------------------------------------------------------------------

/**
 * @brief Advances the running friction calibration by one cycle: move to the
 *        lower angle, then sweep up and down once per speed.
 *
 * @param state Current measurements
 * @param theta Measured angle, θ (rad)
 * @param vel Measured velocity, θ̇ (rad/s)
 * @param torque Measured actuator torque (Nm)
 *
 * @note Aborts (and stops the sweep) if the torque passes the ATC hard limit
 *       or the CW volume changes, since either invalidates the sweep.
 */
void Libra2MotionController::RunFrictionCalibration(
    const Motion::MotionState& state, const double& theta, const double& vel,
    const double& torque) {
    FrictionRun& run = friction_run_;
    t_stage_s_ += state.dt;

    // Abort guards
    std::string abort_reason;
    if (t_stage_s_ > kMoveTimeout) {
        abort_reason = "timed out moving or sweeping";
    } else if (std::abs(torque) > torque_comp_upper_bound_) {
        abort_reason = "torque " + Format(torque)
                       + " Nm is past the hard limit ("
                       + Format(torque_comp_upper_bound_)
                       + " Nm); balance the CW near the window first";
    } else if (!cw_vol_ || std::abs(*cw_vol_ - run.volume) > kRestVolTolerance) {
        abort_reason = "CW volume changed during the sweeps";
    }
    if (!abort_reason.empty()) {
        pending_stop_ = true;
        FinishCalibration(false, abort_reason);
        return;
    }

    const bool up = (status_ == Motion::CalibrationStatus::kFrictionSweepUp);
    const double end =
        (status_ == Motion::CalibrationStatus::kFrictionSweepDown
         || status_ == Motion::CalibrationStatus::kFrictionMovingToStart)
            ? run.angle_lo
            : run.angle_hi;
    const double speed = run.max_speed
                         * kFrictionSpeedFractions.at(run.speed_idx);

    if (status_ != Motion::CalibrationStatus::kFrictionMovingToStart) {
        if (state.trajectory_active) {
            run.trajectory_seen = true;
            AddFrictionSample(theta, vel, torque, up, speed);
            return;
        }
        if (!run.trajectory_seen) {
            return;  // sweep requested but not started yet
        }
    }

    // Wait until the move/sweep has ended at rest at its end
    const bool arrived = !state.trajectory_active
                         && std::abs(theta - end) <= kReachTolerance
                         && std::abs(vel) <= kRestVelTolerance;
    if (!arrived) {
        return;
    }

    switch (status_) {
        case Motion::CalibrationStatus::kFrictionMovingToStart:
            BeginStage(Motion::CalibrationStatus::kFrictionSweepUp);
            break;

        case Motion::CalibrationStatus::kFrictionSweepUp:
            BeginStage(Motion::CalibrationStatus::kFrictionSweepDown);
            break;

        case Motion::CalibrationStatus::kFrictionSweepDown:
            {
                std::string error;
                if (!FinishFrictionSpeed(speed, error)) {
                    FinishCalibration(false, error);
                    return;
                }
                ++run.speed_idx;
                if (run.speed_idx < kFrictionSpeedFractions.size()) {
                    BeginStage(Motion::CalibrationStatus::kFrictionSweepUp);
                } else {
                    FinishFrictionCalibration();
                }
                break;
            }

        default:
            break;
    }
}

/**
 * @brief Bins one sweep sample if it is inside the sampled span and at steady
 *        speed.
 *
 * @param theta Measured angle, θ (rad)
 * @param vel Measured velocity, θ̇ (rad/s)
 * @param torque Measured actuator torque (Nm)
 * @param up Whether this is the up sweep
 * @param speed Sweep speed, v (rad/s)
 */
void Libra2MotionController::AddFrictionSample(const double& theta,
                                               const double& vel,
                                               const double& torque,
                                               const bool& up,
                                               const double& speed) {
    FrictionRun& run = friction_run_;
    const double lo = run.angle_lo + kFrictionSampleMargin;
    const double hi = run.angle_hi - kFrictionSampleMargin;
    if (theta < lo || theta > hi) {
        return;  // ramps and CW swing
    }
    const double vel_ref = up ? speed : -speed;
    if (std::abs(vel - vel_ref) > kFrictionSpeedTolerance * speed) {
        return;  // not at steady speed
    }

    const std::size_t n_bins = run.up_sum.size();
    if (n_bins == 0) {
        return;
    }
    const auto bin = std::min(n_bins - 1, static_cast<std::size_t>(
                                              (theta - lo) / kFrictionBinWidth));
    if (up) {
        run.up_sum[bin] += torque;
        ++run.up_count[bin];
    } else {
        run.down_sum[bin] += torque;
        ++run.down_count[bin];
    }
}

/**
 * @brief Turns one speed's binned sweeps into a friction point, and logs the
 *        gravity curve they also give.
 *
 * @param speed Sweep speed, v (rad/s)
 * @param[out] error Reason, if this speed gave too little data
 *
 * @note From E8 and E9 (`FINDING_ACTUATOR_FRICTION.md`), per angle bin, with
 *       actuator torque (so the bin mean of E9 is the holding torque,
 *       −τ_ext,g):
 *         drag = (τ_up − τ_down) / 2
 *         τ_g(θ) = (τ_up + τ_down) / 2
 */
bool Libra2MotionController::FinishFrictionSpeed(const double& speed,
                                                 std::string& error) {
    FrictionRun& run = friction_run_;
    const double lo = run.angle_lo + kFrictionSampleMargin;
    const bool model_ready = calibrated_ && cw_model_.IsValid();
    const double cw_mass = Libra2Model::CwMass(run.volume);

    Motion::FrictionPoint point;
    point.speed = speed;
    double drag_min = 0.0;
    double drag_max = 0.0;
    double grav_sum = 0.0;
    double model_err_sum = 0.0;

    for (std::size_t i = 0; i < run.up_sum.size(); ++i) {
        if (run.up_count[i] < kFrictionMinBinSamples
            || run.down_count[i] < kFrictionMinBinSamples) {
            continue;
        }
        const double up = run.up_sum[i] / run.up_count[i];
        const double down = run.down_sum[i] / run.down_count[i];
        const double drag = 0.5 * (up - down);
        const double holding = 0.5 * (up + down);

        if (point.n_bins == 0) {
            drag_min = drag;
            drag_max = drag;
        }
        drag_min = std::min(drag_min, drag);
        drag_max = std::max(drag_max, drag);
        point.drag += drag;
        grav_sum += holding;
        if (model_ready) {
            const double theta_bin = lo
                                     + (static_cast<double>(i) + 0.5)
                                           * kFrictionBinWidth;
            model_err_sum += holding + ComputeNetGravTorque(theta_bin, cw_mass);
        }
        ++point.n_bins;
    }

    if (point.n_bins < kFrictionMinBins) {
        error = "only " + std::to_string(point.n_bins)
                + " angle bins had steady samples both ways at " + Format(speed)
                + " rad/s (need " + std::to_string(kFrictionMinBins)
                + "); use a wider window";
        return false;
    }

    const auto n = static_cast<double>(point.n_bins);
    point.drag /= n;
    point.spread = drag_max - drag_min;
    run.points.push_back(point);

    std::string msg = "Friction sweep at " + Format(speed)
                      + " rad/s: drag=" + Format(point.drag) + " Nm (spread "
                      + Format(point.spread) + " Nm over "
                      + std::to_string(point.n_bins)
                      + " bins), mean holding torque=" + Format(grav_sum / n)
                      + " Nm";
    if (model_ready) {
        msg += " (model error " + Format(model_err_sum / n) + " Nm)";
    }
    logger_->Info(msg);
    return true;
}

/**
 * @brief Fits the friction line through all speeds and applies it.
 *
 * @note A negative slope means friction is flat within noise, so b = 0 and τ_c
 *       is the mean drag. A negative τ_c fails the calibration.
 */
void Libra2MotionController::FinishFrictionCalibration() {
    const FrictionRun& run = friction_run_;
    std::vector<double> speeds;
    std::vector<double> drags;
    for (const auto& p : run.points) {
        speeds.push_back(p.speed);
        drags.push_back(p.drag);
    }

    double coulomb = 0.0;
    double viscous = 0.0;
    double residual_rms = 0.0;
    if (!Libra2Model::FitFrictionLine(speeds, drags, coulomb, viscous,
                                      residual_rms)) {
        FinishCalibration(false, "friction line fit failed (need two or more "
                                 "speeds)");
        return;
    }
    if (viscous < 0.0) {
        logger_->Warn("Fitted b is negative (" + Format(viscous)
                      + " Nm*s/rad), so friction looks flat; using b = 0");
        viscous = 0.0;
        coulomb = 0.0;
        for (const double& d : drags) {
            coulomb += d;
        }
        coulomb /= static_cast<double>(drags.size());

        double sum_sq = 0.0;
        for (const double& d : drags) {
            sum_sq += (d - coulomb) * (d - coulomb);
        }
        residual_rms = std::sqrt(sum_sq / static_cast<double>(drags.size()));
    }
    if (coulomb < 0.0) {
        FinishCalibration(false, "fitted tau_c is negative (" + Format(coulomb)
                                     + " Nm); check the run");
        return;
    }

    Motion::FrictionResult result;
    result.coulomb = coulomb;
    result.viscous = viscous;
    result.residual_rms = residual_rms;
    result.angle_lo = run.angle_lo;
    result.angle_hi = run.angle_hi;
    result.volume = run.volume;
    result.points = run.points;

    friction_coulomb_ = coulomb;
    friction_viscous_ = viscous;
    friction_result_ = result;
    FinishCalibration(true,
                      "Friction calibration succeeded: tau_c=" + Format(coulomb)
                          + " Nm, b=" + Format(viscous) + " Nm*s/rad (fit RMS "
                          + Format(residual_rms) + " Nm)");
}
